// Graded gyroid sheet infill inside a scanned body, for PBF-LB/M.
// Pipeline: closed STL -> solid voxels -> 1.5 mm skin -> graded gyroid
// sheet in the core -> powder-escape vents through the floor -> STL.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Globalization;
using System.IO;
using System.Numerics;
using PicoGK;

/// <summary>
/// Gyroid sheet (Schoen 1970) written as the nodal approximation
/// sin x cos y + sin y cos z + sin z cos x = 0 (von Schnering & Nesper 1991).
/// The raw level-set value is divided by its analytic gradient, so the
/// returned value approximates a distance in millimetres and the thickness
/// parameter really is a wall thickness near the mid-surface.
/// </summary>
public sealed class GradedGyroidSheet : IImplicit
{
    readonly float m_fK;            // spatial frequency, 2*pi / cell size (rad/mm)
    readonly float m_fZ0, m_fZ1;    // height range of the thickness grading (mm)
    readonly float m_fT0, m_fT1;    // wall thickness at z0 and at z1 (mm)

    public GradedGyroidSheet(float fCellMM, float fZ0, float fZ1, float fT0, float fT1)
    {
        if (fCellMM <= 0 || fZ1 <= fZ0) throw new ArgumentException("Invalid cell size or grading range");
        m_fK = 2f * MathF.PI / fCellMM;
        m_fZ0 = fZ0; m_fZ1 = fZ1;
        m_fT0 = fT0; m_fT1 = fT1;
    }

    /// <summary>Linear thickness grading along the build direction z.</summary>
    public float fThicknessAt(float fZ)
    {
        float fU = Math.Clamp((fZ - m_fZ0) / (m_fZ1 - m_fZ0), 0f, 1f);
        return m_fT0 + fU * (m_fT1 - m_fT0);
    }

    // PicoGK may evaluate this from several threads: it only reads fields.
    public float fSignedDistance(in Vector3 vec)
    {
        float fX = m_fK * vec.X, fY = m_fK * vec.Y, fZ = m_fK * vec.Z;
        float fSx = MathF.Sin(fX), fCx = MathF.Cos(fX);
        float fSy = MathF.Sin(fY), fCy = MathF.Cos(fY);
        float fSz = MathF.Sin(fZ), fCz = MathF.Cos(fZ);

        // Level-set value of the gyroid in scaled coordinates.
        float fF = fSx * fCy + fSy * fCz + fSz * fCx;

        // Analytic gradient with respect to the scaled coordinates.
        float fGx = fCx * fCy - fSx * fSz;
        float fGy = fCy * fCz - fSx * fSy;
        float fGz = fCz * fCx - fSy * fSz;
        float fGradMM = m_fK * MathF.Sqrt(fGx * fGx + fGy * fGy + fGz * fGz);

        // First-order distance f/|grad f|; the clamp avoids blow-ups at the
        // rare critical points far from the surface, where only the sign matters.
        float fDistMM = fF / MathF.Max(fGradMM, 0.25f * m_fK);

        // Sheet network: inside where |d| <= t/2 (Al-Ketan & Abu Al-Rub 2021).
        return MathF.Abs(fDistMM) - 0.5f * fThicknessAt(vec.Z);
    }
}

public static class GradedGyroidInfill
{
    // Design parameters. All lengths in millimetres.
    const float fSkinMM       = 1.5f;   // solid outer skin around the lattice
    const float fCellMM       = 8.0f;   // gyroid unit cell size
    const float fWallBottomMM = 1.6f;   // sheet thickness at the build plate
    const float fWallTopMM    = 1.0f;   // sheet thickness at the top of the part
    const float fMinWallMM    = 1.0f;   // process assumption, to be confirmed by coupons
    const float fVentDiaMM    = 3.0f;   // powder-escape hole diameter (assumption)

    public static void Main(string[] args)
    {
        // Usage: GradedGyroidInfill <scan.stl> <output folder>
        // 0.3 mm voxels give at least three voxels across the thinnest wall.
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        // Refuse parameters the process assumption cannot print, before any work.
        if (Math.Min(fWallTopMM, Math.Min(fWallBottomMM, fSkinMM)) < fMinWallMM)
            throw new ArgumentException("A wall is thinner than the minimum printable wall");
        if (lib.fVoxelSize > fMinWallMM / 3f)
            throw new ArgumentException($"Voxel size {lib.fVoxelSize} mm cannot resolve {fMinWallMM} mm walls");

        // 1. Load the closed, millimetre-scaled scan mesh and voxelise it.
        using Mesh mshScan = Mesh.mshFromStlFile(strInputPath, Mesh.EStlUnit.MM, libSet: lib);
        using Voxels voxBody = new(mshScan);
        if (voxBody.bIsEmpty()) throw new InvalidDataException("The scan mesh produced no volume; is it closed?");
        BBox3 oBox = voxBody.oCalculateBoundingBox();

        // 2. The core is the body shrunk by the skin thickness. The skin is
        //    what remains between the body and the core.
        using Voxels voxCore = voxBody.voxOffset(-fSkinMM);
        if (voxCore.bIsEmpty()) throw new InvalidDataException("The part is too thin for this skin");

        // 3. Graded gyroid sheet, thicker near the plate. A TPMS is unbounded,
        //    so render it only inside the part's bounding box, then clip it to
        //    the core with a boolean intersection.
        GradedGyroidSheet xGyroid = new(fCellMM, oBox.vecMin.Z, oBox.vecMax.Z, fWallBottomMM, fWallTopMM);
        using Voxels voxGyroid = new(lib, xGyroid, oBox);
        using Voxels voxInfill = voxCore.voxBoolIntersect(voxGyroid);

        // 4. Part = skin + infill. voxBoolSubtract returns a new object.
        using Voxels voxPart = voxBody.voxBoolSubtract(voxCore);
        voxPart.BoolAdd(voxInfill);

        // 5. Powder escape. A gyroid sheet splits the core into two
        //    interpenetrating labyrinths, and both are sealed by the skin.
        //    Vertical vents through the floor, the lowest region in the build
        //    orientation, reach both labyrinths because each vent rises
        //    three quarters of a cell into the core.
        using ScalarField sfCore = new(voxCore);
        Lattice latVents = new(lib);
        int nVents = 0;
        float fPitch = 2f * fCellMM;
        float fProbeZ = oBox.vecMin.Z + fSkinMM + 0.5f * fCellMM;
        for (float fX = oBox.vecMin.X + fCellMM; fX < oBox.vecMax.X - fCellMM; fX += fPitch)
        {
            for (float fY = oBox.vecMin.Y + fCellMM; fY < oBox.vecMax.Y - fCellMM; fY += fPitch)
            {
                // Only drill where the vent actually opens into the core. Outside
                // the narrow band bGetValue returns false but still writes the
                // background value with the correct sign: negative = inside.
                sfCore.bGetValue(new Vector3(fX, fY, fProbeZ), out float fValue);
                if (fValue >= 0)
                    continue;
                Vector3 vecBottom = new(fX, fY, oBox.vecMin.Z - 1f);
                Vector3 vecTop = new(fX, fY, oBox.vecMin.Z + fSkinMM + 0.75f * fCellMM);
                latVents.AddBeam(vecBottom, vecTop, 0.5f * fVentDiaMM, 0.5f * fVentDiaMM, false);
                nVents++;
            }
        }
        if (nVents < 2) throw new InvalidDataException("Fewer than two vents fit; powder would be trapped");
        using Voxels voxVents = new(latVents);
        voxPart.BoolSubtract(voxVents);

        // 6. Export and report. Volume is measured, not assumed.
        Directory.CreateDirectory(strOutputDir);
        using Mesh mshOut = voxPart.mshAsMesh();
        mshOut.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);
        voxBody.CalculateProperties(out float fBodyMM3, out _);
        voxPart.CalculateProperties(out float fPartMM3, out _);
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture,
            "Vents {0}, relative volume {1:F3} of the solid scan", nVents, fPartMM3 / fBodyMM3));
    }
}

// Raw .xyz point cloud -> cleaned points -> sphere splats -> closed solid.
// PicoGK 2.3.0, headless: the caller owns the Library.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Numerics;
using PicoGK;

public static class XyzToClosedSolid
{
    // Reconstruction parameters, in millimetres.
    const float fGapRadiusMM   = 4.0f;  // closes scanner gaps up to about 8 mm across
    const float fMinSplatMM    = 0.6f;  // splat radius floor (several voxels)
    const int   nMinNeighbours = 4;     // radius-outlier threshold

    public static void Main(string[] args)
    {
        // Usage: XyzToClosedSolid <scan.xyz> <output folder>
        using Library lib = new(0.3f);
        Run(lib, args[0], args[1]);
    }

    /// <summary>
    /// Reads "x y z [more columns]" lines. Comments (#), blank lines and
    /// non-finite values are skipped; parsing is culture-invariant so a
    /// French or German locale cannot turn "1.25" into 125.
    /// </summary>
    static List<Vector3> ReadXyz(string strPath)
    {
        List<Vector3> avec = new();
        foreach (string strLine in File.ReadLines(strPath))
        {
            string s = strLine.Trim();                       // tolerate indentation and CRLF
            if (s.Length == 0 || s.StartsWith("#")) continue;
            string[] astr = s.Split(new[] { ' ', '\t', ',' }, StringSplitOptions.RemoveEmptyEntries);
            if (astr.Length < 3) continue;                   // header or truncated row
            if (!float.TryParse(astr[0], NumberStyles.Float, CultureInfo.InvariantCulture, out float fX) ||
                !float.TryParse(astr[1], NumberStyles.Float, CultureInfo.InvariantCulture, out float fY) ||
                !float.TryParse(astr[2], NumberStyles.Float, CultureInfo.InvariantCulture, out float fZ))
                continue;                                    // non-numeric row, e.g. a column header
            Vector3 vec = new(fX, fY, fZ);
            // float.TryParse accepts "NaN" and "Infinity"; drop them here.
            if (float.IsFinite(vec.X) && float.IsFinite(vec.Y) && float.IsFinite(vec.Z)) avec.Add(vec);
        }
        return avec;
    }

    /// <summary>Uniform hash grid for fixed-radius neighbour queries.</summary>
    sealed class HashGrid
    {
        readonly float m_fCell;                                        // cell edge in mm
        readonly Dictionary<(int, int, int), List<int>> m_oCells = new(); // cell -> point indices
        readonly List<Vector3> m_avec;

        public HashGrid(List<Vector3> avec, float fCell)
        {
            m_avec = avec; m_fCell = fCell;
            // One pass buckets every point; queries then scan 27 cells.
            for (int i = 0; i < avec.Count; i++)
            {
                var key = Key(avec[i]);
                if (!m_oCells.TryGetValue(key, out var list)) m_oCells[key] = list = new List<int>();
                list.Add(i);
            }
        }

        // Floor, not truncation, so negative coordinates land in the right cell.
        (int, int, int) Key(Vector3 v) => ((int)MathF.Floor(v.X / m_fCell), (int)MathF.Floor(v.Y / m_fCell), (int)MathF.Floor(v.Z / m_fCell));

        /// <summary>Number of other points within fRadius (fRadius <= cell size).</summary>
        public int nNeighbours(int iPoint, float fRadius)
        {
            Vector3 v = m_avec[iPoint];
            var (cx, cy, cz) = Key(v);
            int n = 0;
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++)
                    for (int dz = -1; dz <= 1; dz++)
                        if (m_oCells.TryGetValue((cx + dx, cy + dy, cz + dz), out var list))
                            foreach (int j in list)
                                if (j != iPoint && Vector3.DistanceSquared(v, m_avec[j]) <= fRadius * fRadius) n++;
            return n;
        }

        /// <summary>Distance to the nearest other point, or cell size if none is close.</summary>
        public float fNearest(int iPoint)
        {
            Vector3 v = m_avec[iPoint];
            var (cx, cy, cz) = Key(v);
            float fBest = m_fCell;                       // cap: "nothing close"
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++)
                    for (int dz = -1; dz <= 1; dz++)
                        if (m_oCells.TryGetValue((cx + dx, cy + dy, cz + dz), out var list))
                            foreach (int j in list)
                                if (j != iPoint) fBest = MathF.Min(fBest, Vector3.Distance(v, m_avec[j]));
            return fBest;
        }
    }

    public static void Run(Library lib, string strInputPath, string strOutputDir)
    {
        // 1. Read and sanity-check the cloud.
        List<Vector3> avecRaw = ReadXyz(strInputPath);
        // Refuse instead of guessing when the file is mostly unreadable.
        if (avecRaw.Count < 1000) throw new InvalidDataException($"Only {avecRaw.Count} valid points");

        // 2. Typical spacing = median nearest-neighbour distance on a sample.
        HashGrid oCoarse = new(avecRaw, 2.0f);
        List<float> afNearest = new();
        for (int i = 0; i < avecRaw.Count; i += Math.Max(1, avecRaw.Count / 2000))
            afNearest.Add(oCoarse.fNearest(i));
        afNearest.Sort();                            // median ignores sparse outliers
        float fSpacing = afNearest[afNearest.Count / 2];

        // 3. Radius outlier removal: real surface points have neighbours,
        //    reflections and clutter floating in space do not.
        float fRadius = Math.Clamp(4f * fSpacing, 0.5f, 2.0f);   // <= hash cell size (2 mm)
        List<Vector3> avec = new();                  // cleaned cloud
        for (int i = 0; i < avecRaw.Count; i++)
            if (oCoarse.nNeighbours(i, fRadius) >= nMinNeighbours) avec.Add(avecRaw[i]);
        Console.WriteLine($"{avecRaw.Count} points, spacing {fSpacing:F3} mm, kept {avec.Count}");

        // 4. Splat every point as a sphere. Overlapping spheres form a thin
        //    shell around the true surface: a dilation of the point set by a ball (Serra (1982)).
        float fSplat = MathF.Max(fMinSplatMM, 1.5f * fSpacing);  // overlap neighbouring splats
        Lattice lat = new(lib);                      // spheres are exact implicit primitives
        foreach (Vector3 vec in avec) lat.AddSphere(vec, fSplat);
        using Voxels voxShell = new(lat);            // narrow-band level set (Museth (2013))

        // 5. Close scanner gaps: dilate until the shell is watertight. The
        //    dilated shell's outer surface sits fSplat + fGapRadius outside.
        voxShell.Offset(fGapRadiusMM);

        // 6. Solidify. Meshing the shell and re-voxelising the mesh classifies
        //    every region not reachable from outside as inside, which fills
        //    the hollow interior of the shell.
        using Mesh mshShell = voxShell.mshAsMesh();
        using Voxels voxSolid = new(mshShell);

        // 7. Erode back by the same total amount: dilation then erosion is a
        //    morphological closing, so the outer surface returns to the scan.
        voxSolid.Offset(-(fGapRadiusMM + fSplat));
        if (voxSolid.bIsEmpty()) throw new InvalidDataException("Reconstruction collapsed; check units and gap radius");

        // 8. Light smoothing of the sphere ripple, smaller than any feature.
        voxSolid.TripleOffset(lib.fVoxelSize);

        // 9. Export in millimetres and report what was built.
        Directory.CreateDirectory(strOutputDir);
        using Mesh mshOut = voxSolid.mshAsMesh();
        mshOut.SaveToStlFile(Path.Combine(strOutputDir, "part.stl"), Mesh.EStlUnit.MM);
        voxSolid.CalculateProperties(out float fVolumeMM3, out BBox3 oBox);
        Console.WriteLine(string.Format(CultureInfo.InvariantCulture, "Volume {0:F0} mm3, size {1}", fVolumeMM3, oBox.vecSize()));
    }
}
